            ctx->file_exif = 1;

            if(!chunk.length) return SPNG_EEXIF;

            struct spng_exif exif;

            exif.data = spng__malloc(ctx, chunk.length);
            if(exif.data == NULL) return SPNG_EMEM;

            memcpy(exif.data, data, chunk.length);
